//! The board core against the web's own build (tests/fixtures/boards.json, generated by the web's hardware.ts and
//! ground.ts through the TS harness in the scratchpad): part counts, items (order, names, boxes, tops), the support
//! field at 1000 samples per board, and the bounds.

use std::collections::BTreeMap;

use apz_board::Board;
use serde_json::Value;

const FIXTURE: &str = include_str!("fixtures/boards.json");
const TOL: f64 = 1e-6;

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("fixture parses")
}

fn nums(v: &Value) -> Vec<f64> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|x| x.as_f64().expect("number"))
        .collect()
}

#[test]
fn boards_and_variants_match_the_web_build() {
    let fx = fixture();
    // The boards with no params: each one's parts, items, bounds and support field.
    {
        let boards = fx["boards"].as_object().expect("boards");
        assert_eq!(boards.len(), 6);
        for (kind, want) in boards {
            check(kind, &BTreeMap::new(), want);
        }
    }
    // The same boards with params (gpus, amd, studio, cooler, p_cores...): the `when`s, the counts and the `use`s.
    {
        let variants = fx["variants"].as_array().expect("variants");
        assert!(variants.len() >= 5);
        for v in variants {
            let kind = v["kind"].as_str().unwrap();
            let params: BTreeMap<String, f64> = v["params"]
                .as_object()
                .unwrap()
                .iter()
                .map(|(k, x)| (k.clone(), x.as_f64().unwrap()))
                .collect();
            check(&format!("{kind} {params:?}"), &params, v);
        }
    }
}

/// Compares one board (built with `params`) with its fixture entry: parts, items (names, boxes, tops), bounds, support.
fn check(kind: &str, params: &BTreeMap<String, f64>, want: &Value) {
    let b = Board::from_kind(want["kind"].as_str().unwrap_or(kind), params);
    assert_eq!(
        b.part_count(),
        want["parts"].as_u64().unwrap() as usize,
        "{kind}: part count"
    );

    let items = want["items"].as_array().unwrap();
    assert_eq!(b.parts().len(), items.len(), "{kind}: item count");
    let mut worst_box = 0.0_f64;
    let mut tops_checked = 0;
    for (i, (got, exp)) in b.parts().iter().zip(items).enumerate() {
        assert_eq!(
            got.name,
            exp["name"].as_str().unwrap(),
            "{kind}: item {i} name"
        );
        let bx = nums(&exp["box"]);
        let have = [
            got.bounds.min[0],
            got.bounds.min[1],
            got.bounds.min[2],
            got.bounds.max[0],
            got.bounds.max[1],
            got.bounds.max[2],
        ];
        for k in 0..6 {
            let d = (have[k] - bx[k]).abs();
            worst_box = worst_box.max(d);
            assert!(
                d <= TOL,
                "{kind}: item {i} ({}) box[{k}] {} vs {} (off {d})",
                got.name,
                have[k],
                bx[k]
            );
        }
        match (got.top, exp["top"].as_f64()) {
            (Some(t), Some(e)) => {
                tops_checked += 1;
                assert!((t - e).abs() <= TOL, "{kind}: item {i} top {t} vs {e}");
            }
            (None, None) => {}
            (g, e) => panic!("{kind}: item {i} top {g:?} vs {e:?}"),
        }
    }

    let bounds = nums(&want["bounds"]);
    let bb = b.bounds();
    let have = [
        bb.min[0], bb.min[1], bb.min[2], bb.max[0], bb.max[1], bb.max[2],
    ];
    for k in 0..6 {
        assert!(
            (have[k] - bounds[k]).abs() <= TOL,
            "{kind}: bounds[{k}] {} vs {}",
            have[k],
            bounds[k]
        );
    }

    let mut worst_support = 0.0_f64;
    let mut hits = 0;
    let samples = want["samples"].as_array().unwrap();
    for s in samples {
        let v = nums(s);
        let got = b.support_top(v[0], v[1]).unwrap_or(0.0);
        if got > 0.0 {
            hits += 1;
        }
        let d = (got - v[2]).abs();
        worst_support = worst_support.max(d);
        assert!(
            d <= TOL,
            "{kind}: support at ({}, {}) {got} vs {}",
            v[0],
            v[1],
            v[2]
        );
    }
    println!(
        "{kind} {params:?}: items {} (tops compared {tops_checked}) worst box deviation {worst_box:e}; support samples {} hits {hits} worst deviation {worst_support:e}",
        items.len(),
        samples.len()
    );
}
